    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        isLoading = true;
        try
        {
            profile = await SettingsService.GetProfileAsync();
            ResetFields();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ResetFields()
    {
        if (profile is null) return;
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        statusMessage = null;
        isSaving = true;
        try
        {
            var updated = profile! with { DisplayName = displayName, Email = email, Bio = bio };
