            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        ResetFields();
        statusMessage = null;
    }

    private void HandleAvatarError() { /* image failed to load — keep placeholder */ }
}

