            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>
    </div>

    <div class="card mb-3">
        <div class="card-body">
            <h6 class="card-title mb-3">Muted Channels</h6>
            @if (allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                @foreach (var channel in allChannels)
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                    </div>
                }
            }
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
        @(isSaving ? "Saving…" : "Save Preferences")
    </button>
}

@code {
    private NotificationPrefs? prefs;
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        try
        {
            prefs = await SettingsService.GetNotificationPrefsAsync();
            emailNotifications = prefs.EmailNotifications;
            pushNotifications = prefs.PushNotifications;
            weeklyDigest = prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(prefs.MutedChannels);
            // Use the channels from the loaded prefs as the known channel list.
            // In a real app this would come from a separate API call.
            allChannels = prefs.MutedChannels.ToList();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        statusMessage = null;
        isSaving = true;
        try
        {
            var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(updated);
            prefs = updated;
            statusMessage = "Notification preferences saved.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save preferences: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}

@namespace sv_d344f047fe444c5285b057c597bb05e2.Components.Pages.Settings
@using sv_d344f047fe444c5285b057c597bb05e2.Models
@inject ISettingsService SettingsService

<h4 class="mb-4">Security</h4>

@if (isLoading)
{
    <div class="text-center py-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (settings is not null)
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <small class="text-muted">
                        @if (settings.TwoFactorEnabled)
                        {
                            <span class="badge bg-success me-1">Enabled</span>
                            <span>Your account has an extra layer of security.</span>
                        }
                        else
                        {
                            <span class="badge bg-warning text-dark me-1">Disabled</span>
                            <span>Enable 2FA to secure your account.</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@settings.TwoFactorEnabled" disabled
                           title="Contact support to change 2FA settings" />
                </div>
            </div>
            @if (settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </small>
            }
        </div>
    </div>

    <div class="card mb-3">
        <div class="card-header">
            <h6 class="mb-0">Active Sessions</h6>
        </div>
        <div class="card-body p-0">
            @if (settings.Sessions.Count == 0)
            {
                <p class="text-muted p-3 mb-0">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th class="text-end">Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in settings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td class="text-end">
                                        @if (session == settings.Sessions[0])
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => sessionToRevoke = session">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </div>
    </div>

    <RevokeSessionDialog Session="sessionToRevoke"
                         OnConfirm="HandleRevokeSession"
                         OnCancel="() => sessionToRevoke = null" />
}

@code {
    private SecuritySettings? settings;
    private ActiveSession? sessionToRevoke;
    private bool isLoading = true;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
    }

    private async Task LoadSettings()
    {
        isLoading = true;
        try
        {
            settings = await SettingsService.GetSecuritySettingsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        statusMessage = null;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            sessionToRevoke = null;
            await LoadSettings();
            statusMessage = "Session revoked successfully.";
            isError = false;
        }
        catch (Exception ex)
        {
            sessionToRevoke = null;
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
    }
}

