@using sv_d344f047fe444c5285b057c597bb05e2.Models
@inject ISettingsService SettingsService

<h4 class="mb-4">Appearance</h4>

@if (isLoading)
{
    <div class="text-center py-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title mb-3">Theme</h6>
                    @foreach (var t in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                   value="@t" checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title mb-3">Font Size</h6>
                    @foreach (var fs in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{fs}")"
                                   value="@fs" checked="@(fontSize == fs)"
                                   @onchange="() => fontSize = fs" />
                            <label class="form-check-label" for="@($"fs-{fs}")">@fs</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title mb-3">Language</h6>
                    <select class="form-select" @bind="language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                    <small class="text-muted">Reduce spacing and padding throughout the interface.</small>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                @(isSaving ? "Saving…" : "Save")
            </button>
        </div>

        <div class="col-md-5">
            <div class="card sticky-top" style="top: 1rem;">
                <div class="card-header">
                    <h6 class="mb-0">Live Preview</h6>
                </div>
                <div class="card-body @PreviewBgClass" style="@PreviewStyle">
                    <div class="@(compactMode ? "mb-1" : "mb-3")">
                        <h6 class="@PreviewTextClass" style="@PreviewFontStyle">Sample Heading</h6>
                        <p class="@PreviewTextClass mb-1" style="@PreviewFontStyle">
                            This is a preview of your chosen appearance settings.
                        </p>
                    </div>
                    <div class="d-flex gap-2 @(compactMode ? "mb-1" : "mb-2")">
                        <button class="btn btn-sm @PreviewBtnClass" style="@PreviewFontStyle">Button</button>
                        <button class="btn btn-sm @PreviewBtnOutlineClass" style="@PreviewFontStyle">Outline</button>
                    </div>
                    <div class="@(compactMode ? "p-1" : "p-2") rounded @PreviewCardClass">
                        <small class="@PreviewTextClass" style="@PreviewFontStyle">
                            📌 Card element &middot; @LanguageDisplayName &middot; @fontSize font
                        </small>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            theme = settings.Theme;
            fontSize = settings.FontSize;
            language = settings.Language;
            compactMode = settings.CompactMode;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SaveAppearance()
    {
        statusMessage = null;
        isSaving = true;
        try
        {
            await SettingsService.SaveAppearanceAsync(new AppearanceSettings(theme, fontSize, language, compactMode));
            statusMessage = "Appearance settings saved.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save settings: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private string PreviewFontStyle => fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 0.95rem;"
    };

    private string PreviewStyle => theme == "Dark"
        ? "background-color: #1e1e1e; min-height: 160px;"
        : "min-height: 160px;";

    private string PreviewBgClass => theme == "Dark" ? "bg-dark" : "bg-light";
    private string PreviewTextClass => theme == "Dark" ? "text-light" : "text-dark";
    private string PreviewBtnClass => theme == "Dark" ? "btn-light" : "btn-primary";
    private string PreviewBtnOutlineClass => theme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
    private string PreviewCardClass => theme == "Dark" ? "bg-secondary" : "bg-white border";

    private string LanguageDisplayName => language switch
    {
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => "English"
    };
}
