arguments.file_text:
@page "/settings"
@namespace sv_d344f047fe444c5285b057c597bb05e2.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <aside class="settings-nav">
        <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="s => activeSection = s" />
    </aside>

    <section class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </section>
</div>

@code {
    private string activeSection = "Profile";
}

.settings-layout {
    display: flex;
    gap: 1.5rem;
    min-height: 70vh;
}

.settings-nav {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-sidebar {
    position: sticky;
    top: 4.5rem;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0.375rem;
    padding: 0.5rem 0.75rem;
    margin-bottom: 0.125rem;
    transition: background-color 0.15s;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

@media (max-width: 768px) {
    .settings-layout {
        flex-direction: column;
    }

    .settings-nav {
        flex: none;
    }

    ::deep .settings-sidebar .nav {
        flex-direction: row !important;
        overflow-x: auto;
    }

    ::deep .settings-sidebar .nav-item {
        flex-shrink: 0;
    }
}

